jedi.api.helpers.validate_line_column.wr:
@wraps(func)
def wrapper(self, line=None, column=None, *args, **kwargs):
    line = (max(len(self._code_lines), 1) if line is None else line)
    if not 0 < line <= len(self._code_lines):
        raise ValueError('`line` parameter is not in a valid range.')
    line_string = self._code_lines[line - 1]
    line_len = len(line_string)
    if line_string.endswith('\r\n'):
        line_len -= 2
    elif line_string.endswith('\n'):
        line_len -= 1
    column = (line_len if column is None else column)
    if not 0 <= column <= line_len:
        raise ValueError('`column` parameter (%d) is not in a valid range (0-%d) for line %d (%r).' % (column, line_len, line, line_string))
    return func(self, line, column, *args, **kwargs)

jedi.plugins.pytest.goto_anonymous_param:
def goto_anonymous_param(func):

    def wrapper(param_name):
        (is_pytest_param, param_name_is_function_name) = _is_a_pytest_param_and_inherited(param_name)
        if is_pytest_param:
            names = _goto_pytest_fixture(param_name.get_root_context(), param_name.string_name, skip_own_module=param_name_is_function_name)
            if names:
                return names
        return func(param_name)
    return wrapper

jedi.cache.memoize_method.wrapper:
@wraps(method)
def wrapper(self, *args, **kwargs):
    cache_dict = self.__dict__.setdefault('_memoize_method_dct', {})
    dct = cache_dict.setdefault(method, {})
    key = (args, frozenset(kwargs.items()))
    try:
        return dct[key]
    except KeyError:
        result = method(self, *args, **kwargs)
        dct[key] = result
        return result
